export function relation(text) {
  const chars = [...text];
  let found = null;
  for (let pos = 0; pos < chars.length; pos++) {
    if (chars[pos] === '>') {
      found = { pos };
      break;
    }
  }
  if (!found) return null;
  const left = chars.slice(0, found.pos).join('').trim();
  const [name, quoted] = stripQuotedSuffix(left);
  return name + '|' + quoted;
}

// Called with a string only: the package's JavaScript declares no type.
function stripQuotedSuffix(s) {
  const t = s.trimEnd();
  if (t.endsWith('"')) {
    const rest = t.slice(0, -1);
    const q = rest.lastIndexOf('"');
    if (q !== -1) return [rest.slice(0, q).trimEnd(), rest.slice(q + 1)];
  }
  return [t, ''];
}

export function lastOf(text, needle) {
  const t = text.trim();
  return t.lastIndexOf(needle);
}

export function lastUndefined(text) {
  const t = text.trim();
  return t.lastIndexOf();
}
